UPDATE companies SET description='Extreme Power House operates from Las Vegas, Nevada, as an online retailer specializing in aftermarket performance parts for European and American sports cars. The company’s founding year and ownership structure are not publicly disclosed, though customer testimonials reference a team led by an individual named Mike.

The business stocks a range of bolt-on upgrades including ECU tunes, cold-air intakes, front-mount intercoolers, charge pipes, downpipes, and cat-back exhaust systems for platforms such as BMW, Audi, Ford Mustang, Volkswagen, Porsche, and the Nissan GT-R. It functions as a reseller, carrying brands like Active Autowerke, and manages order fulfillment, a price-match guarantee, a loyalty-points program, and financing through PayPal Credit.

Reviews highlight transactions from international buyers, including a customer in Singapore, indicating the company ships globally.

Extreme Power House emphasizes competitive pricing, backed by a $25 store credit if a lower advertised price is found, and promotes its customer service as a key differentiator. The site also features a BBB A+ rating and maintains active social-media channels on Facebook, Instagram, YouTube, and a blog.', certifications=ARRAY[]::text[], profile='{"capabilities": ["E-commerce retail", "Order fulfillment", "Price matching", "Loyalty rewards program", "Financing via PayPal Credit", "Customer service"], "industries": ["Automotive aftermarket", "Performance parts"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Price-match guarantee with $25 store credit for lower prices", "Loyalty rewards program (1 point per $1 spent)", "PayPal Credit financing (6 months, no interest)", "International shipping demonstrated by customer review from Singapore", "BBB A+ rating"], "facts_used": ["Company name: Extreme Power House -> db", "Headquarters: Las Vegas, Nevada -> db", "Business description: aftermarket parts for BMW, Audi, Ford Mustang, VW, Porsche, Nissan GTR -> /", "Products carried: ECU tunes, air intakes, front mount intercoolers, charge pipes, downpipes, axle back and catback exhausts -> /", "Brand carried: Active Autowerke -> /", "Price match guarantee with $25 store credit -> /", "Loyalty rewards program (1 point per $1) -> /", "Buy now pay later with PayPal Credit (6 months no interest) -> /", "Customer testimonials referencing Mike and team -> /", "International customer review from Singapore -> /", "BBB rating A+ -> /", "Social media presence: Facebook, Instagram, YouTube, Blog -> /", "Business hours: 8AM-5PM Pacific Time -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "XPH is your home for BMW, Audi, Ford Mustang, VW, Porsche and Nissan GTR aftermarket parts.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links"