UPDATE companies SET description='Fisher Auto Parts traces its roots to 1929 in Weston, West Virginia, when Blair Coiner founded Coiner Parts during the Great Depression. Coiner began by supplying auto parts to car dealers, service stations, and independent garages, emphasizing high-character dealer service.

The company rebranded as Fisher Auto Parts in 1983 after expanding to 60 locations and 300 employees. Today, the headquarters in Weston operates with a staff of 18, overseeing a network of retail stores and Federated Car Care Centers. Fisher distributes quality name-brand parts from major manufacturers, offering an online catalog (Federated Link Catalog), safety data sheets, technical training, and maintenance resources such as tech tips and the "Two Guys Garage Tech Talk" series.

Fisher serves the automotive aftermarket, including car dealerships, service stations, repair garages, professional technicians, and retail customers. Its store locator and car care repair center locator connect drivers and shops with local inventory and service.

Founded on perseverance and a commitment to exceeding expectations in value, quality, and service, Fisher differentiates itself through fast, dependable delivery and a focus on pleasing each customer with the service they deserve.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Auto parts wholesale distribution", "Retail auto parts sales", "Car care repair center network", "Technical training programs", "Safety data sheet (SDS) provision", "Technical tips and vehicle maintenance guidance", "Online parts catalog (Federated Link Catalog)"], "industries": ["Automotive aftermarket", "Auto repair and maintenance", "Car dealerships", "Service stations", "Garages"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Fast, dependable delivery service", "Quality name-brand parts at affordable prices", "Network of retail stores and Federated Car Care Centers", "Technical training and maintenance resources (SDS sheets, tech tips)", "Online Federated Link Catalog for parts lookup"], "facts_used": ["Founded 1929 by Blair Coiner in Weston, West Virginia -> db", "Original name Coiner Parts, renamed Fisher Auto Parts in 1983 after 60 stores/300 employees -> db", "Current headcount 18 at headquarters -> db", "Headquarters location Weston, West Virginia -> db", "Business model: selling auto parts to dealers, service stations, garages -> db", "Store locator, car care repair center locator, Federated Link Catalog, training, SDS sheets, tech tips, vehicle maintenance resources -> pages[\"/\"]", "Claims: fast dependable delivery, quality name-brand parts at affordable prices, exceeding expectations in value/quality/service -> db"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "He started by selling auto parts to car dealers, service stations and garages.", "founded_year": "1929", "employee_count": "18", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links