UPDATE companies SET description='Flair Flexible Packaging, operating as Flair USA, is headquartered in Appleton, Wisconsin. The company was founded in 1992 and remains privately held and family-owned. It began as a flexible packaging manufacturer and has grown into a vertically integrated operation with facilities across North America and Asia.

The company produces flexible packaging films, pouches, and bags through extrusion, converting, flexographic printing (up to 10 colors), solventless lamination, and rotogravure printing. Its Appleton site houses an extrusion facility, a converting facility, an analytical lab, and an application lab. The firm offers both custom-engineered structures — including coextruded and laminated films for hot-fill, high-pressure processing, and retort applications — and a stock program of unprinted rollstock, lidding, and vacuum pouches.

Flair serves food and non-food markets such as meat and poultry, seafood, cheese and dairy, prepared foods, snacks and sweets, baby food, grains and spices, fruits and vegetables, coffee and tea, liquids and spreads, pet care, and foodservice. Customers range from national brands to regional processors seeking tailored barrier performance, shelf-life extension, and sustainable formats.

The company emphasizes vertical integration as a differentiator, controlling quality from resin extrusion through final conversion. It highlights its FSSC 22000-certified food safety system, FDA/USDA/CFIA compliance, and collaborative development model that includes factory acceptance testing, shelf-life validation, and on-site engineering support.', certifications=ARRAY['FSSC 22000','FDA compliant','USDA compliant','CFIA compliant']::text[], profile='{"capabilities": ["Extrusion", "Converting", "Flexographic printing (10-color)", "Solventless lamination", "Rotogravure printing", "Coextrusion (COEX)", "Lamination", "Lidding film manufacturing", "Thermoforming film manufacturing", "Vacuum pouch manufacturing", "Rollstock film manufacturing", "Pouch and bag manufacturing", "Sustainable packaging development", "Tactile packaging", "Oxygen scavenging film production", "Oxygen absorber sachet production (ACTIV8)", "Factory Acceptance Testing (FAT)", "Shelf-life testing", "Analytical lab testing", "Application development", "Technical services & development", "Engineering support", "Field services"], "industries": ["Food", "Nonfood", "Meat & Poultry", "Seafood", "Cheese & Dairy", "Prepared Foods", "Snacks & Sweets", "Baby Foods", "Grains, Spices & Baking", "Fruits & Vegetables", "Coffee & Tea", "Liquids & Spreads", "Pets & Animal Care", "Foodservice & Institutional"], "materials": ["Polyethylene (PE) mono-material", "Coextruded (COEX) films", "Laminated films", "Lidding films", "High barrier films", "Oxygen scavenging films", "PFA-free food-grade materials"], "equipment": ["10-color flexographic press", "Solventless laminator", "Rotogravure press", "Extrusion lines", "Converting lines"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Vertically integrated from extrusion through converting", "FSSC 22000 certified food safety management system", "Stock program with lower minimums and faster lead times", "Custom structures for hot fill, HPP, and retort", "Rotogravure printing and full graphics support"], "facts_used": ["Founded 1992 -> db", "Headquarters Appleton, Wisconsin -> db, /about", "Privately held and family-owned -> /about", "FSSC 22000 certification -> /about", "FDA, USDA, CFIA compliant -> /about", "Extrusion Facility, Converting Facility, Analytical Lab, Application Lab -> /", "10-color flexo printing, solventless lamination, 35,000 sq ft plant in Calgary -> /", "Rotogravure printing -> /about", "Markets served: food & nonfood, meat & poultry, seafood, cheese & dairy, prepared foods, snacks & sweets, baby foods, grains/spices/baking, fruits & vegetables, coffee & tea, liquids & spreads, pets & animal care, foodservice & institutional -> /", "Stock program with lower minimums and faster lead times -> /about", "Custom structures for hot fill, HPP, retort -> /about", "Oxygen scavenging films and ACTIV8 absorbers -> /", "Vertically integrated -> /", "Locations in Canada, Seattle, Mexico, Korea -> /about", "Factory Acceptance Testing participation -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Flair Flexible Packaging is celebrating 30 years of manufacturing flexible packaging solutions", "founded_year": "1992", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='flair-usa' AND approved AND profile IS NULL;
UPDATE companies SET description='Flat-To-Form Metal Specialties, Inc. was founded in 1995 in Fremont, Michigan, where it operates a sheet metal fabrication shop serving manufacturers across the region and beyond.

The shop provides a full range of custom fabrication services, including turret punching (24 gauge to 7 gauge), shearing, forming, MIG/TIG/spot/stud welding, laser cutting, plasma cutting, tapping, press‑in fastener installation, assembly of hinges, gaskets and hardware, and custom prototyping. Materials processed include stainless steel, aluminum, cold‑rolled steel, galvanized, galvannealed, hot‑rolled pickled & oiled, and fish paper. The company handles orders from single prototypes to runs of thousands of assembled pieces, though no fixed facility size or headcount is disclosed.

Customers span general manufacturing, lubrication‑system builders (Mighty Lube Systematic Lubrication in Fremont and OPCO Lubrication Systems in West Michigan), office‑furniture makers, and gas‑pump manufacturers. The firm emphasizes delivery flexibility, offering local pickup, UPS, FedEx, and freight trucking from its Fremont location.

Flat‑To‑Form highlights its ISO 9001:2015‑certified quality system, backed by internal audits, management reviews, and annual surveillance audits, as a core differentiator. It also promotes a one‑stop‑shop model that combines punching, forming, welding, laser, plasma, assembly and finishing under one roof, plus rapid prototyping for design validation.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Custom fabrication", "MIG welding", "TIG welding", "Spot welding", "Stud welding", "Turret punching (24 gauge to 7 gauge)", "Shearing", "Forming", "Laser cutting", "Plasma cutting", "Tapping", "Press-in fastener installation", "Assembly (hinges, fasteners, gaskets, hardware)", "Custom prototyping", "Finishing services"], "industries": ["Manufacturing", "Lubrication systems", "Office furniture manufacturing", "Gas pump manufacturing"], "materials": ["Stainless steel", "Aluminum", "Cold rolled steel", "Galvanized steel", "Hot rolled pickled & oiled steel", "Galvannealed steel", "Fish paper"], "equipment": ["Turret punch press"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ISO 9001:2015 certified quality system with internal audits and annual surveillance", "One-stop shop for punching, forming, welding, laser, plasma, assembly and finishing", "Custom prototyping from single pieces to small batches", "Delivery and shipping options including UPS, FedEx, freight and local pickup", "Over 20 years of production crew experience"], "facts_used": ["Founded 1995 in Fremont, MI -> /about-us", "ISO 9001:2015 certified -> /about-us", "Capabilities: punching, shearing, forming, welding (MIG, TIG, spot, stud), laser, plasma, tapping, press-in fasteners, assembly, prototyping -> /services", "Materials: stainless steel, aluminum, cold rolled steel, galvanized, galvannealed, hot rolled pickled & oiled, fish paper -> /", "Industries served: manufacturing, lubrication systems (Mighty Lube, OPCO), office furniture, gas pumps -> /about-us", "Equipment: turret punch press -> /services", "Delivery options: local pickup, UPS, FedEx, freight -> /about-us", "Quality system: internal audits, management reviews, annual surveillance -> /about-us", "Headquarters: 9577 W. 40th Street, Fremont, MI 49412 -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Flat-To-Form Metal Specialties, Inc is a sheet metal fabrication business located in Fremont, Michigan since 1995.", "founded_year": "1995", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='flat-to-form-metal-specialties-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Flint Creek Woodworks was founded in the fall of 2006 in Gentry, Arkansas, initially operating as a cabinet door shop.

The company designs, builds, finishes, and installs custom cabinets for kitchens, bathrooms, home offices, and whole-home projects. Its manufacturing facility employs advanced CNC technology for precision machining, while its proprietary DuraSmooth™ finishing system provides a durable, high-quality surface. Construction features all-wood boxes with fully captured dado joinery, screwed-together assembly, soft-close drawer guides, and flush ends, with premium finishes included as standard.

Flint Creek works with large-scale contractors, remodeling professionals, and individual homeowners, delivering tailored cabinetry for new construction and renovation projects. Its client base spans the residential construction and home remodeling sectors, with a focus on kitchen and bath applications.

The business emphasizes a collaborative, direct-to-customer approach, with on-staff professionals handling every phase from design through installation. The company cites its combination of traditional woodworking craftsmanship and modern CNC precision, along with a no-shortcuts construction philosophy, as the foundation of its reputation for durable, refined cabinetry.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cabinet design", "CNC machining", "Cabinet manufacturing", "Finishing (DuraSmooth)", "Installation", "Dado joinery", "Screwed-box assembly", "Soft-close hardware installation"], "industries": ["Residential construction", "Home remodeling", "Custom cabinetry", "Kitchen and bath"], "materials": ["Wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["All-wood cabinet boxes with fully captured dado joinery and screwed-together construction", "Proprietary DuraSmooth\u2122 finish system developed for custom cabinetry", "On-staff professionals manage design, manufacturing, finishing, and installation", "Advanced CNC technology for precision machining", "Premium finishes and soft-close hardware included as standard"], "facts_used": ["Founded in fall 2006 as a cabinet door shop -> /about", "Headquartered in Gentry, Arkansas -> db", "Offers custom cabinets for kitchens, bathrooms, home offices -> /", "Uses advanced CNC technology for precision machining -> /about", "Proprietary DuraSmooth\u2122 finish system -> /", "On-staff professionals handle installation -> /", "Serves large-scale contractors, remodeling professionals, and homeowners -> /about", "All-wood construction with captured dado joinery and screwed-together boxes -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Flint Creek Woodworks was established in the fall of 2006 as a cabinet door shop and has grown to offer a full line of custom cabinets.", "founded_year": "2006", "employee_count": "", "cage_code": "", 